  <main class="studio-shell">
    <header class="topbar">
      <a class="brand" href="/" aria-label="${Z(`Volver a josicovila.com`,`Back to josicovila.com`)}">
        <img class="brand-logo" src="/jvstudio/logo.png" alt="JV Studio · Make music anywhere" />
      </a>

      <label class="project-field">
        <span>${Z(`Proyecto`,`Project`)}</span>
        <input data-project-name aria-label="${Z(`Nombre del proyecto`,`Project name`)}" readonly />
      </label>

      <div class="transport" aria-label="${Z(`Transporte`,`Transport`)}">
        <button class="transport-button stop-button" type="button" data-action="stop" aria-label="${Z(`Detener reproducción`,`Stop playback`)}">
          <span aria-hidden="true">■</span>
        </button>
        <button class="transport-button play-button" type="button" data-action="play" aria-label="${Z(`Iniciar reproducción`,`Start playback`)}">
          <span aria-hidden="true">▶</span>
        </button>
        <button class="transport-button pause-button" type="button" data-action="pause" aria-label="${Z(`Pausar reproducción`,`Pause playback`)}" title="${Z(`Pausa · Espacio`,`Pause · Space`)}">
          <span aria-hidden="true">Ⅱ</span>
        </button>
        <span class="transport-status" data-status>${Z(`Listo`,`Ready`)}</span>
      </div>

      <label class="tempo-field">
        <input type="number" min="40" max="240" step="1" data-bpm aria-label="${Z(`Tempo en pulsaciones por minuto`,`Tempo in beats per minute`)}" />
        <span>BPM</span>
      </label>

      <div class="signature" aria-label="${Z(`Compás`,`Time signature`)}">
        <strong data-signature></strong>
        <span>${Z(`Compás`,`Meter`)}</span>
      </div>

      <div class="future-actions" aria-label="${Z(`Acciones de proyecto`,`Project actions`)}">
        <button type="button" data-action="open-project">${Z(`Abrir`,`Open`)}</button>
        <button type="button" data-action="save-project">${Z(`Guardar`,`Save`)}</button>
        <button type="button" data-action="export-wav">${Z(`Exportar WAV`,`Export WAV`)}</button>
        <button class="top-help" type="button" data-action="help" aria-label="${Z(`Ayuda: guía y atajos`,`Help: guide and shortcuts`)}">? ${Z(`Ayuda`,`Help`)}</button>
      </div>
      <div class="instrument-load" data-instrument-load hidden role="status" aria-live="polite">
        <span data-instrument-load-label></span>
        <progress data-instrument-load-progress max="100" value="0"></progress>
      </div>
    </header>

    <section class="workspace" aria-label="${Z(`Espacio de trabajo de JV Studio`,`JV Studio workspace`)}">
      <aside class="track-column">
        <div class="panel-heading">
          <span>${Z(`PISTAS`,`TRACKS`)}</span>
          <button type="button" data-action="add-track" aria-label="${Z(`Añadir pista`,`Add track`)}" title="${Z(`Añadir pista`,`Add track`)}">＋</button>
        </div>
        <div class="track-list" data-track-list></div>
        <div class="inspector" data-inspector></div>
      </aside>

      <div class="workspace-divider" data-workspace-divider role="separator" tabindex="0" aria-label="${Z(`Cambiar ancho de pistas y Arranger`,`Resize tracks and Arranger`)}"><span></span></div>

      <section class="arranger-panel">
        <div class="arranger-header">
          <div class="arranger-heading">
            <div class="view-switch" aria-label="${Z(`Panel activo`,`Active panel`)}">
              <button class="is-active" type="button" data-view="arranger" aria-pressed="true">ARRANGER</button>
              <button type="button" data-view="piano-roll" data-action="piano-roll" aria-pressed="false">PIANO ROLL</button>
              <button type="button" data-view="mixer" aria-pressed="false">MIXER</button>
            </div>
            <strong>${Z(`Línea de tiempo del proyecto`,`Project timeline`)}</strong>
          </div>
          <div class="arranger-tools">
            <label class="project-length-control" title="${Z(`Duración del proyecto: 1–1024 compases`,`Project length: 1–1024 bars`)}">
              <span>${Z(`COMPASES`,`BARS`)}</span>
              <input type="number" min="1" max="1024" step="1" data-project-length aria-label="${Z(`Duración del proyecto en compases`,`Project length in bars`)}" />
            </label>
            <label class="arranger-zoom-control">
              <span>ZOOM</span>
              <select data-arranger-zoom aria-label="${Z(`Zoom del Arranger`,`Arranger zoom`)}">
                <option value="fit">${Z(`Ajustar`,`Fit project`)}</option>
                <option value="12">25%</option>
                <option value="24">50%</option>
                <option value="48">100%</option>
                <option value="96">200%</option>
                <option value="192">400%</option>
              </select>
            </label>
            <span class="range-copy" data-range></span>
            <button type="button" data-action="add-clip">＋ ${Z(`Nuevo clip`,`New clip`)}</button>
            <button type="button" data-action="duplicate-clip" title="Ctrl+D">${Z(`Duplicar`,`Duplicate`)}</button>
            <button type="button" data-action="delete-clip" title="${Z(`Supr`,`Delete`)}">${Z(`Borrar`,`Delete`)}</button>
          </div>
        </div>

        <div class="timeline-shell" aria-hidden="true"><span></span><div class="timeline-viewport"><div class="timeline" data-timeline></div></div></div>
        <div class="arrangement" data-arrangement tabindex="0" aria-label="${Z(`Arranger. Las flechas mueven clips; Ctrl+D duplica; Supr borra; Escape cancela el arrastre.`,`Arranger. Arrow keys move clips; Ctrl+D duplicates; Delete removes; Escape cancels drag.`)}"></div>

        <footer class="milestone-note">
          <span class="pulse-dot" aria-hidden="true"></span>
          <div role="status" aria-live="polite"><strong data-selection-title>${Z(`Arranger preparado`,`Arranger ready`)}</strong><p data-selection-copy>${Z(`Selecciona una pista o clip. Haz doble clic en un hueco para crear un clip de un compás.`,`Select a track or clip. Double-click an empty lane to create a one-bar clip.`)}</p></div>
        </footer>

        <section class="mixer-panel" data-mixer-panel hidden aria-label="${Z(`Mezclador del proyecto`,`Project mixer`)}">
          <div class="mixer-divider" data-mixer-divider role="separator" tabindex="0" aria-label="${Z(`Cambiar altura de Arranger y Mixer`,`Resize Arranger and Mixer`)}"><span></span></div>
          <div class="mixer-content" data-mixer-content></div>
        </section>
      </section>
    </section>

    <section class="mobile-notice">
      <strong>${Z(`JV Studio necesita una pantalla más grande.`,`JV Studio needs a larger screen.`)}</strong>
      <p>${Z(`Esta primera versión está diseñada para navegadores de escritorio.`,`This first version is designed for desktop browsers.`)}</p>
    </section>
    <input type="file" accept=".json,.jvstudio.json,application/json" data-project-file hidden />
  </main>
